public class OrdersService(ILogger<OrdersService> logger)
{
    public async Task<Order> CreateAsync(CreateOrderDto dto, CancellationToken ct)
    {
        logger.LogInformation("Creating order for {UserId} with {LineCount} lines",
            dto.UserId, dto.Lines.Count);

        try
        {
            var order = await _repo.SaveAsync(dto, ct);
            logger.LogInformation("Order {OrderId} created", order.Id);
            return order;
        }
        catch (DbUpdateException ex)
        {
            logger.LogError(ex, "Failed to create order for {UserId}", dto.UserId);
            throw;
        }
    }
}

app.Use(async (ctx, next) =>
{
    var correlationId = ctx.Request.Headers["X-Correlation-Id"].FirstOrDefault()
        ?? Activity.Current?.TraceId.ToString()
        ?? Guid.NewGuid().ToString("N");

    ctx.Response.Headers["X-Correlation-Id"] = correlationId;

    using (logger.BeginScope(new Dictionary<string, object>
    {
        ["CorrelationId"] = correlationId,
        ["RequestPath"] = ctx.Request.Path.Value ?? ""
    }))
    {
        await next();
    }
});

